javascript:
try {
  const menu = document.getElementById('dynamic-menu');
  if (menu) {
    let currentDropdown = null;
    let currentDropdownMenu = null;

    Array.from(menu.children).forEach(li => {
      const a = li.querySelector('a');
      if (!a) return;
      const text = a.textContent.trim();

      if (text.startsWith('_')) {
        // Este item e filho do dropdown anterior
        a.textContent = text.substring(1).trim();
        a.classList.remove('nav-link');
        a.classList.add('dropdown-item');

        if (!currentDropdown && li.previousElementSibling) {
          currentDropdown = li.previousElementSibling;
          currentDropdown.classList.add('dropdown');

          const parentA = currentDropdown.querySelector('a');
          parentA.classList.add('dropdown-toggle');
          parentA.setAttribute('data-bs-toggle', 'dropdown');
          parentA.setAttribute('role', 'button');
          parentA.setAttribute('aria-expanded', 'false');

          currentDropdownMenu = document.createElement('ul');
          currentDropdownMenu.classList.add('dropdown-menu', 'border-0', 'shadow-sm', 'mt-2');
          currentDropdown.appendChild(currentDropdownMenu);
        }

        if (currentDropdownMenu) {
          const newLi = document.createElement('li');
          newLi.appendChild(a);
          currentDropdownMenu.appendChild(newLi);
          li.remove();
        }
      } else {
        // Item normal — encerra qualquer dropdown aberto
        currentDropdown = null;
        currentDropdownMenu = null;
      }
    });
  }
} catch(e) { console.error('Menu dropdown:', e); }
